static void ck(bool b,const char*s){printf("%s %s\n",b?"PASS":"FAIL",s);fflush(stdout);if(!b)ExitProcess(1);++checks;}
static std::vector<BYTE> bytes(const std::wstring&p){FILE*f=_wfopen(p.c_str(),L"rb");if(!f)return {};fseek(f,0,SEEK_END);auto n=ftell(f);rewind(f);std::vector<BYTE>b(n);fread(b.data(),1,n,f);fclose(f);return b;}
static void put(const std::wstring&p,const std::wstring&s){FILE*f=_wfopen(p.c_str(),L"wb");ck(f!=nullptr,"fixture write");WORD bom=0xfeff;fwrite(&bom,2,1,f);fwrite(s.data(),2,s.size(),f);fclose(f);}
static void iconAt(const std::wstring& path,const std::wstring& icon,int index=0){IShellLinkW*l=nullptr;IPersistFile*f=nullptr;ck(SUCCEEDED(CoCreateInstance(CLSID_ShellLink,nullptr,CLSCTX_INPROC_SERVER,IID_PPV_ARGS(&l))),"shell link");l->QueryInterface(IID_PPV_ARGS(&f));ck(SUCCEEDED(f->Load(path.c_str(),STGM_READ)),"load link");l->SetIconLocation(icon.c_str(),index);ck(SUCCEEDED(f->Save(path.c_str(),TRUE)),"change user icon");f->Release();l->Release();}
static void solidIcon(const std::wstring&p){std::vector<BYTE>b(22+40+128*128*4+128*16,0);auto word=[&](int off,WORD v){memcpy(b.data()+off,&v,2);};auto dword=[&](int off,DWORD v){memcpy(b.data()+off,&v,4);};word(2,1);word(4,1);b[6]=b[7]=128;word(10,1);word(12,32);dword(14,(DWORD)b.size()-22);dword(18,22);dword(22,40);dword(26,128);dword(30,256);word(34,1);word(36,32);for(int i=0;i<128*128;++i){b[62+i*4]=60;b[63+i*4]=30;b[64+i*4]=200;b[65+i*4]=255;}FILE*f=_wfopen(p.c_str(),L"wb");ck(f!=nullptr,"custom icon handle");fwrite(b.data(),1,b.size(),f);fclose(f);}
static COLORREF pixel(const std::wstring&p,int x,int y){HICON i=(HICON)LoadImageW(nullptr,p.c_str(),IMAGE_ICON,128,128,LR_LOADFROMFILE);ck(i!=nullptr,"load icon pixel fixture");ICONINFO info{};GetIconInfo(i,&info);BITMAPINFO bi{};bi.bmiHeader.biSize=sizeof(BITMAPINFOHEADER);bi.bmiHeader.biWidth=128;bi.bmiHeader.biHeight=-128;bi.bmiHeader.biPlanes=1;bi.bmiHeader.biBitCount=32;std::vector<BYTE>b(128*128*4);HDC dc=GetDC(nullptr);ck(GetDIBits(dc,info.hbmColor,0,128,b.data(),&bi,DIB_RGB_COLORS)==128,"read icon pixels");ReleaseDC(nullptr,dc);DeleteObject(info.hbmMask);DeleteObject(info.hbmColor);DestroyIcon(i);auto q=&b[(y*128+x)*4];return RGB(q[2],q[1],q[0]);}
struct Link{std::wstring icon,target,args,description,working;int index=0,show=0;WORD hotkey=0;};
static Link info(const std::wstring&p){Link out;IShellLinkW*l=nullptr;IPersistFile*f=nullptr;ck(SUCCEEDED(CoCreateInstance(CLSID_ShellLink,nullptr,CLSCTX_INPROC_SERVER,IID_PPV_ARGS(&l))),"inspect link");l->QueryInterface(IID_PPV_ARGS(&f));ck(SUCCEEDED(f->Load(p.c_str(),STGM_READ)),"read link");wchar_t b[32768]{};l->GetIconLocation(b,32768,&out.index);out.icon=b;l->GetPath(b,32768,nullptr,SLGP_RAWPATH);out.target=b;l->GetArguments(b,32768);out.args=b;l->GetDescription(b,32768);out.description=b;l->GetWorkingDirectory(b,32768);out.working=b;l->GetShowCmd(&out.show);l->GetHotkey(&out.hotkey);f->Release();l->Release();return out;}
