 ck(FolderBadge::apply(store,src,error),"legacy source badge fixture");ck(DeleteFileW(link.c_str()),"external delete shortcut");auto result=EntryMaintenance::reconcile();ck(result.removed==1&&entries.size()==3,"external deletion prunes committed custom entry");loadConfig();ck(entries.size()==3,"prune persists");ck(GetFileAttributesW((src+L"\\desktop.ini").c_str())==INVALID_FILE_ATTRIBUTES,"last reference restores legacy badge");
